CREATE EXTENSION IF NOT EXISTS pgcrypto;
CREATE EXTENSION IF NOT EXISTS btree_gist;
CREATE TABLE users (id UUID PRIMARY KEY DEFAULT gen_random_uuid(), email VARCHAR(255) NOT NULL UNIQUE, password_hash VARCHAR(255) NOT NULL, first_name VARCHAR(100) NOT NULL, last_name VARCHAR(100) NOT NULL, role VARCHAR(20) NOT NULL CHECK (role IN ('PATIENT','DOCTOR','ADMIN')), active BOOLEAN NOT NULL DEFAULT TRUE, created_at TIMESTAMPTZ NOT NULL DEFAULT now(), updated_at TIMESTAMPTZ NOT NULL DEFAULT now());
CREATE TABLE patient_profiles (user_id UUID PRIMARY KEY REFERENCES users(id) ON DELETE CASCADE, phone VARCHAR(30), date_of_birth DATE, preferred_location VARCHAR(120));
CREATE TABLE departments (id UUID PRIMARY KEY DEFAULT gen_random_uuid(), name VARCHAR(120) NOT NULL UNIQUE, description TEXT, created_at TIMESTAMPTZ NOT NULL DEFAULT now());
CREATE TABLE doctor_profiles (user_id UUID PRIMARY KEY REFERENCES users(id) ON DELETE CASCADE, specialty VARCHAR(120) NOT NULL, bio TEXT, location VARCHAR(120), rating NUMERIC(2,1) DEFAULT 5.0);
CREATE TABLE doctor_departments (doctor_id UUID NOT NULL REFERENCES doctor_profiles(user_id), department_id UUID NOT NULL REFERENCES departments(id), PRIMARY KEY(doctor_id,department_id));
CREATE TABLE doctor_availability (id UUID PRIMARY KEY DEFAULT gen_random_uuid(), doctor_id UUID NOT NULL REFERENCES doctor_profiles(user_id), day_of_week SMALLINT NOT NULL CHECK(day_of_week BETWEEN 0 AND 6), starts_at TIME NOT NULL, ends_at TIME NOT NULL, slot_minutes SMALLINT NOT NULL DEFAULT 30 CHECK(slot_minutes BETWEEN 10 AND 120), active BOOLEAN NOT NULL DEFAULT TRUE, CHECK(ends_at > starts_at));
CREATE TABLE appointments (id UUID PRIMARY KEY DEFAULT gen_random_uuid(), patient_id UUID NOT NULL REFERENCES patient_profiles(user_id), doctor_id UUID NOT NULL REFERENCES doctor_profiles(user_id), starts_at TIMESTAMPTZ NOT NULL, ends_at TIMESTAMPTZ NOT NULL, status VARCHAR(20) NOT NULL CHECK(status IN ('BOOKED','CONFIRMED','CANCELLED','COMPLETED','NO_SHOW')), appointment_type VARCHAR(20) NOT NULL CHECK(appointment_type IN ('IN_PERSON','VIDEO','PHONE')), reason VARCHAR(240), version BIGINT NOT NULL DEFAULT 0, created_at TIMESTAMPTZ NOT NULL DEFAULT now(), updated_at TIMESTAMPTZ NOT NULL DEFAULT now(), CHECK(ends_at > starts_at));
ALTER TABLE appointments ADD CONSTRAINT no_doctor_time_overlap EXCLUDE USING gist (doctor_id WITH =, tstzrange(starts_at,ends_at,'[)') WITH &&) WHERE (status IN ('BOOKED','CONFIRMED'));
CREATE INDEX appointments_patient_start_idx ON appointments(patient_id,starts_at DESC);
CREATE INDEX appointments_doctor_start_idx ON appointments(doctor_id,starts_at DESC);
CREATE TABLE appointment_notes (id UUID PRIMARY KEY DEFAULT gen_random_uuid(), appointment_id UUID NOT NULL REFERENCES appointments(id) ON DELETE CASCADE, author_id UUID NOT NULL REFERENCES users(id), body TEXT NOT NULL, created_at TIMESTAMPTZ NOT NULL DEFAULT now());
CREATE TABLE medical_documents (id UUID PRIMARY KEY DEFAULT gen_random_uuid(), patient_id UUID NOT NULL REFERENCES patient_profiles(user_id), uploaded_by UUID NOT NULL REFERENCES users(id), file_name VARCHAR(255) NOT NULL, file_type VARCHAR(120) NOT NULL, file_size BIGINT NOT NULL CHECK(file_size BETWEEN 1 AND 10485760), storage_key VARCHAR(512) NOT NULL UNIQUE, created_at TIMESTAMPTZ NOT NULL DEFAULT now());
CREATE INDEX documents_patient_created_idx ON medical_documents(patient_id,created_at DESC);
CREATE TABLE notifications (id UUID PRIMARY KEY DEFAULT gen_random_uuid(), user_id UUID NOT NULL REFERENCES users(id), type VARCHAR(40) NOT NULL, title VARCHAR(160) NOT NULL, body TEXT NOT NULL, read_at TIMESTAMPTZ, created_at TIMESTAMPTZ NOT NULL DEFAULT now());
CREATE INDEX notifications_user_created_idx ON notifications(user_id,created_at DESC);
CREATE TABLE audit_logs (id UUID PRIMARY KEY DEFAULT gen_random_uuid(), user_id UUID REFERENCES users(id), action VARCHAR(60) NOT NULL, entity_type VARCHAR(60) NOT NULL, entity_id UUID, ip_address INET, metadata JSONB NOT NULL DEFAULT '{}'::jsonb, created_at TIMESTAMPTZ NOT NULL DEFAULT now());
CREATE INDEX audit_created_idx ON audit_logs(created_at DESC);
CREATE TABLE refresh_tokens (id UUID PRIMARY KEY DEFAULT gen_random_uuid(), user_id UUID NOT NULL REFERENCES users(id) ON DELETE CASCADE, token_hash VARCHAR(128) NOT NULL UNIQUE, expires_at TIMESTAMPTZ NOT NULL, revoked_at TIMESTAMPTZ, created_at TIMESTAMPTZ NOT NULL DEFAULT now());
CREATE TABLE event_inbox (event_id UUID PRIMARY KEY, received_at TIMESTAMPTZ NOT NULL DEFAULT now());
